// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address caller, address queryAddr, uint256 depositAmount) public {
        vm.assume(caller != address(0));
        vm.assume(queryAddr != address(0));
        vm.assume(queryAddr != caller);
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2);

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.addToBalance{value: depositAmount}();

        vm.prank(caller);
        uint256 returned = c.getBalance(queryAddr);
        uint256 actualBalanceOfQueryAddr = c.getBalance(queryAddr);
        vm.prank(queryAddr);
        uint256 selfBalance = c.getBalance(queryAddr);
        assertTrue(returned == selfBalance);
    }
}
